import {imageData,videoData} from './intake-media.js';
import {escapeHTML as e} from './station-workspace.js';
export function createStationMedia({api,root,redraw,onSaved,onError}){
 let photos=[],video='',caption='',shared=false,key=crypto.randomUUID(),busy=false,locked=false;
 const reset=()=>{photos=[];video='';caption='';shared=false;key=crypto.randomUUID();locked=false;};
 const remember=()=>{if(locked)return;caption=root.querySelector('#media-caption')?.value??caption;shared=root.querySelector('#media-shared')?.checked??shared;};
 function render(){return `<section class="online-card"><h2>补充照片与视频</h2><p class="online-note">上传你观察时拍下的内容，保存到这位伙伴的长期档案。</p><div class="media-upload-previews">${photos.map(url=>`<img src="${e(url)}" alt="待保存的宠物照片">`).join('')}${video?`<video src="${e(video)}" controls playsinline></video>`:''}</div><fieldset ${busy||locked?'disabled':''}><div class="media-upload-buttons"><label class="button secondary">拍照<input type="file" data-media-file="photo" accept="image/*" capture="environment" hidden></label><label class="button secondary">录视频<input type="file" data-media-file="video" accept="video/mp4,video/webm" capture="environment" hidden></label><label class="button secondary">选相册<input type="file" data-media-file="album" accept="image/*" multiple hidden></label></div><p class="online-note">每次最多 3 张照片或一段 30 秒、10 MB 内的视频</p><label>补充说明<input id="media-caption" value="${e(caption)}" maxlength="1000" placeholder="例如：今天第一次靠近志愿者"></label><label class="check-label spaced"><input type="checkbox" id="media-shared" ${shared?'checked':''}><span>向领养者展示这些影像<small>未勾选时仅本站可见。</small></span></label></fieldset><button class="button primary full spaced" type="button" data-media-save ${busy||(!photos.length&&!video)?'disabled':''}>${busy?'正在保存…':locked?'重试保存这批素材':'保存到宠物档案'}</button>${locked?'<p class="online-note">这批内容已锁定，重试不会重复添加。</p>':''}</section>`;}
 async function change(event){const input=event.target.closest('[data-media-file]');if(!input||busy||locked)return;remember();busy=true;redraw();try{if(input.dataset.mediaFile==='video'){video=(await videoData(input.files[0])).dataUrl;}else{const files=Array.from(input.files||[]);if(files.length+photos.length>3)throw Error('每次最多添加 3 张照片。');photos.push(...await Promise.all(files.map(imageData)));}}catch(err){onError(err.message);}finally{busy=false;redraw();}}
 async function save(petId){if(busy)return;remember();busy=true;locked=true;redraw();try{await api.addVisuals(petId,{photos,video:video||undefined,caption,shared},key);reset();busy=false;await onSaved();}catch(err){onError(err.message);}finally{busy=false;redraw();}}
 return {render,change,save,remember,reset,get busy(){return busy;}};
}

